181	                std::lock_guard<std::mutex> lock(state_mutex);
182	                dev_id = connected_dev_id;
183	            }
184	            PrintParams params;
185	            params.dev_id = dev_id;
186	            start_local_print(params, nullptr, nullptr);
187	            std::cout << "scenario started" << std::endl;
188	        } else if (cmd == "stop") {
