208	int FakePrinterAgent::run_scenario(PrintParams params, OnUpdateStatusFn update_fn, WasCancelledFn cancel_fn)
209	{
210	    std::vector<FakePrinterStatusStep> scenario;
211	    {
212	        std::lock_guard<std::mutex> lock(state_mutex);
213	        scenario = m_scenario;
214	    }
215	
216	    if (update_fn)
217	        update_fn(PrintingStageCreate, 0, "Preparing...");
218	
219	    std::string dev_id = params.dev_id;
220	    for (const auto& step : scenario) {
221	        if (m_stop_requested || (cancel_fn && cancel_fn())) {
222	            if (update_fn)
223	                update_fn(PrintingStageERROR, 0, "Cancelled");
224	            {
225	                std::lock_guard<std::mutex> lock(m_scenario_done_mutex);
226	                m_scenario_running = false;
227	            }
228	            m_scenario_done_cv.notify_all();
229	            return BAMBU_NETWORK_SUCCESS;
230	        }
231	        std::this_thread::sleep_for(std::chrono::milliseconds(step.delay_ms));
232	        emit_status(dev_id, step, true);
233	    }
234	
235	    if (update_fn)
236	        update_fn(PrintingStageFinished, 100, "Print finished");
237	
238	    {
239	        std::lock_guard<std::mutex> lock(m_scenario_done_mutex);
240	        m_scenario_running = false;
241	    }
