void FakePrinterAgent::run_debug_console()
{
    print_console_help();

    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        std::string        cmd;
        iss >> cmd;

        if (cmd.empty()) {
            continue;
        } else if (cmd == "quit" || cmd == "exit") {
            break;
        } else if (cmd == "connect") {
            std::string dev_id;
            if (!(iss >> dev_id))
                dev_id = "FAKE001";
            connect_printer(dev_id, "127.0.0.1", "", "", false);
            std::cout << "connected " << dev_id << std::endl;
        } else if (cmd == "disconnect") {
            disconnect_printer();
            std::cout << "disconnected" << std::endl;
        } else if (cmd == "scenario") {
            std::string dev_id;
            {
                std::lock_guard<std::mutex> lock(state_mutex);
                dev_id = connected_dev_id;
            }
            PrintParams params;
            params.dev_id = dev_id;
            start_local_print(params, nullptr, nullptr);
            std::cout << "scenario started" << std::endl;
        } else if (cmd == "stop") {
            cancel_scenario();
            std::cout << "scenario stopped" << std::endl;
        } else if (cmd == "status") {
            FakePrinterStatusStep step;
            if (!(iss >> step.gcode_state >> step.mc_percent >> step.mc_remaining_time >> step.nozzle_temper >>
                  step.nozzle_target_temper >> step.bed_temper >> step.bed_target_temper)) {
                std::cout << "usage: status <state> <percent> <remaining_min> <nozzle> <nozzle_tgt> <bed> <bed_tgt>" << std::endl;
                continue;
            }
            push_status(step);
            std::cout << "status pushed" << std::endl;
        } else if (cmd == "help") {
            print_console_help();
        } else {
            std::cout << "unknown command: " << cmd << " (try 'help')" << std::endl;
        }
    }
}

int FakePrinterAgent::run_scenario(PrintParams params, OnUpdateStatusFn update_fn, WasCancelledFn cancel_fn)
{
    std::vector<FakePrinterStatusStep> scenario;
    {
        std::lock_guard<std::mutex> lock(state_mutex);
        scenario = m_scenario;
    }

    if (update_fn)
        update_fn(PrintingStageCreate, 0, "Preparing...");

    std::string dev_id = params.dev_id;
    for (const auto& step : scenario) {
        if (m_stop_requested || (cancel_fn && cancel_fn())) {
            if (update_fn)
                update_fn(PrintingStageERROR, 0, "Cancelled");
            {
                std::lock_guard<std::mutex> lock(m_scenario_done_mutex);
                m_scenario_running = false;
            }
            m_scenario_done_cv.notify_all();
            return BAMBU_NETWORK_SUCCESS;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(step.delay_ms));
        emit_status(dev_id, step, true);
    }

    if (update_fn)
        update_fn(PrintingStageFinished, 100, "Print finished");

    {
        std::lock_guard<std::mutex> lock(m_scenario_done_mutex);
        m_scenario_running = false;
    }
    m_scenario_done_cv.notify_all();
    return BAMBU_NETWORK_SUCCESS;
}

